--
-- Estrutura stand-in para vista `vw_dashboard_vendas`
-- (Veja abaixo para a view atual)
--
CREATE TABLE `vw_dashboard_vendas` (
`data_venda` date
,`nome_loja` varchar(50)
,`bairro` varchar(50)
,`nome_produto` varchar(100)
,`categoria` varchar(50)
,`quantidade` int(11)
,`faturamento_total` decimal(20,2)
,`lucro_liquido` decimal(21,2)
);

-- --------------------------------------------------------

--
-- Estrutura para vista `vw_dashboard_vendas`
--
DROP TABLE IF EXISTS `vw_dashboard_vendas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_dashboard_vendas`  AS SELECT `f`.`data_venda` AS `data_venda`, `l`.`nome_loja` AS `nome_loja`, `l`.`bairro` AS `bairro`, `p`.`nome_produto` AS `nome_produto`, `p`.`categoria` AS `categoria`, `f`.`quantidade` AS `quantidade`, `f`.`quantidade`* `f`.`valor_unitario` AS `faturamento_total`, `f`.`quantidade`* `f`.`valor_unitario` - `f`.`quantidade` * `p`.`preco_custo` AS `lucro_liquido` FROM ((`fato_vendas` `f` join `dim_loja` `l` on(`f`.`id_loja` = `l`.`id_loja`)) join `dim_produto` `p` on(`f`.`id_produto` = `p`.`id_produto`))  ;

